	/** 
	 * jumpstart the process by instantiating2 Opportunity
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		opportunityId = OpportunityService.getOpportunityInstance()
		.createOpportunity( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		OpportunityService.getOpportunityInstance()
				.createOpportunity( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.opportunitySubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Opportunity : " + successValue.getOpportunityId());
							  if (successValue.getOpportunityId().equals(opportunityId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfOpportunityList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Opportunity test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on opportunity consumed")
					);
			subscriber.opportunitySubscribe( opportunityId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Opportunity : " + successValue.getOpportunityId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfOpportunityList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on opportunity for opportunityId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Opportunity. 
	 */
	protected Opportunity read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Opportunity" );

		Opportunity entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Opportunity with primary key" );
		msg.append( opportunityId );
		
		OpportunityFetchOneSummary fetchOneSummary = new OpportunityFetchOneSummary( opportunityId );

		try {
			entity = OpportunityService.getOpportunityInstance().getOpportunity( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Opportunity " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Opportunity.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Opportunity." );

		StringBuilder msg = new StringBuilder( "Failed to update a Opportunity : " );        
		Opportunity entity = read();
		UpdateOpportunityCommand command = generateUpdateCommand();
		command.setOpportunityId(entity.getOpportunityId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Opportunity." );

			// for use later on...
			opportunityId = entity.getOpportunityId();

			OpportunityService proxy = OpportunityService.getOpportunityInstance();  

			proxy.updateOpportunity( command ).get();

			LOGGER.info( "-- Successfully saved Opportunity - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + opportunityId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Opportunity.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Opportunity." );

		Opportunity entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Opportunity with id " + opportunityId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Opportunity with id " + opportunityId );

			throw e;
		}

		try{
			OpportunityService.getOpportunityInstance().delete( new DeleteOpportunityCommand( entity.getOpportunityId() ) ).get();
			LOGGER.info( "-- Successfully deleted Opportunity with id " + opportunityId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Opportunity with id " + opportunityId );

			throw e;
		}
	}

	/**
	 * get all Opportunitys.
	 */
	protected List<Opportunity> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Opportunitys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Opportunity : " );        
		List<Opportunity> collection  = new ArrayList<>();

		try {
			// call the static get method on the OpportunityService
			collection = OpportunityService.getOpportunityInstance().getAllOpportunity();
			assertNotNull( collection, "An Empty collection of Opportunity was incorrectly returned.");
			
			// Now print out the values
			Opportunity entity = null;            
			Iterator<Opportunity> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getOpportunityId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

